/* GroupInvitationMapper.findByGroupId */
SELECT gi.*, u.sp_user_id AS sent_by_sp_user_id
FROM group_invitation gi
LEFT JOIN `user` u ON gi.sent_by = u.user_no
WHERE gi.group_id = #{groupId}
ORDER BY gi.created_at DESC

/* GroupInvitationMapper.findById */
SELECT * FROM group_invitation
WHERE id = #{id}

/* GroupInvitationMapper.findByGroupIdAndEmailAndStatus */
SELECT * FROM group_invitation
WHERE group_id = #{groupId} AND email = #{email} AND status = #{status}
LIMIT 1

